import java.util.*;
import java.io.*;

public class Main {

    public static double[] inpf(BufferedReader br) throws IOException {
        String[] parts = br.readLine().trim().split("\\s+");
        double[] a = new double[parts.length];
        for (int i = 0; i < parts.length; i++) {
            a[i] = Double.parseDouble(parts[i]);
        }
        return a;
    }

    public static String[] inps(BufferedReader br) throws IOException {
        return br.readLine().trim().split("\\s+");
    }

    public static long kaijo(int n) {
        long r = 1000000007L;
        if (n < 2) return 1;
        long memo = 1;
        for (int u = 2; u <= n; u++) {
            memo = (memo * u) % r;
        }
        return memo;
    }

    public static int[] na(int n, int d) {
        int[] arr = new int[n];
        Arrays.fill(arr, d);
        return arr;
    }

    public static int[][] na2(int n, int m, int d) {
        int[][] arr = new int[n][m];
        for (int i = 0; i < n; i++) {
            Arrays.fill(arr[i], d);
        }
        return arr;
    }

    public static int[][][] na3(int n, int m, int l, int d) {
        int[][][] arr = new int[n][m][l];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                Arrays.fill(arr[i][j], d);
            }
        }
        return arr;
    }

    public static int[] inp(BufferedReader br) throws IOException {
        String[] parts = br.readLine().trim().split("\\s+");
        int[] a = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            a[i] = Integer.parseInt(parts[i]);
        }
        return a;
    }

    public static long r_up(long a, long b) {
        return (a + b - 1) / b;
    }

    public static long sum(int[] a) {
        long s = 0;
        for (int v : a) s += v;
        return s;
    }

    public static List<int[]> primeDivision(long n) {
        List<int[]> res = new ArrayList<>();
        long num = n;
        for (long p = 2; p * p <= num; p++) {
            if (num % p == 0) {
                int cnt = 0;
                while (num % p == 0) {
                    num /= p;
                    cnt++;
                }
                res.add(new int[]{(int) p, cnt});
            }
        }
        if (num > 1) {
            res.add(new int[]{(int) num, 1});
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = inp(br)[0];

        List<int[]> d = primeDivision(n);
        if (d.size() == 1) {
            System.out.println(d.get(0)[0]);
        } else {
            System.out.println(1);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
import java.util.ArrayList;

public class Main {

    // Helper to read integers
    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    // Prime factorization: returns list of [prime, exponent]
    static ArrayList<int[]> primeDivision(long n) {
        ArrayList<int[]> res = new ArrayList<>();
        long x = n;

        for (long p = 2; p * p <= x; p++) {
            if (x % p == 0) {
                int cnt = 0;
                while (x % p == 0) {
                    x /= p;
                    cnt++;
                }
                res.add(new int[]{(int) p, cnt});
            }
        }
        if (x > 1) {
            res.add(new int[]{(int) x, 1});
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long n = fs.nextInt();

        ArrayList<int[]> d = primeDivision(n);
        if (d.size() == 1) {
            System.out.println(d.get(0)[0]);
        } else {
            System.out.println(1);
        }
    }
}

